	/** The name for exactly [text], or null when it is not one entry. */
	fun nameOf(text: String): String? = NAMES[text]

	/** The longest entry starting at [at]: its name and where it ends. */
	fun matchAt(text: String, at: Int): Pair<String, Int>? {
		var len = minOf(MAX_LENGTH, text.length - at)
		while (len > 0) {
			val hit = NAMES[text.substring(at, at + len)]
			if (hit != null) return hit to at + len
			len--
		}
		return null
	}

	/**
	 * Modifier characters, meaningless alone: variation selectors, the
	 * joiner, skin tones, tags and the keycap mark. Answers the UTF-16
	 * units one takes at [at], or nought when it takes none.
	 */
	fun modifierLengthAt(text: String, at: Int): Int {
		if (at < 0 || at >= text.length) return 0
		val c = text[at]
		if (c == '\uFE0E' || c == '\uFE0F' || c == '\u200D' || c == '\u20E3') return 1
		if (at + 1 >= text.length) return 0
		val d = text[at + 1]
		if (c == '\uD83C' && d in '\uDFFB'..'\uDFFF') return 2
		if (c == '\uDB40' && d in '\uDC20'..'\uDC7F') return 2
		return 0
	}
}
